mapper.update:
update orders
status = #{status}, pay_status = #{payStatus}, pay_method = #{payMethod}, paid_at = #{paidAt}, ready_at = #{readyAt}, picked_at = #{pickedAt}, cancel_reason = #{cancelReason}, rejection_reason = #{rejectionReason}, cancel_time = #{cancelTime}, slot_released = #{slotReleased},
where id = #{id}

update orders
status = #{orders.status}, pay_status = #{orders.payStatus}, paid_at = #{orders.paidAt}, ready_at = #{orders.readyAt}, picked_at = #{orders.pickedAt}, cancel_reason = #{orders.cancelReason}, rejection_reason = #{orders.rejectionReason}, cancel_time = #{orders.cancelTime}, slot_released = #{orders.slotReleased},
where id = #{orders.id} and status = #{expectedStatus}

mapper.select:
select * from orders

    and number like concat('%', #{number}, '%')
    and user_id = #{userId}
    and stall_id = #{stallId}
    and status = #{status}
    and order_time >= #{beginTime}
    and order_time <= #{endTime}

order by order_time desc

select sum(amount) from orders

    and order_time >= #{beginTime}
    and order_time <= #{endTime}
    and status = #{status}

select count(id) from orders

    and order_time >= #{beginTime}
    and order_time <= #{endTime}
    and status = #{status}

select od.name, sum(od.number) as number from orders o join order_detail od on od.order_id = o.id
o.status = 50 and o.order_time >= #{beginTime} and o.order_time <= #{endTime}
group by od.name order by number desc limit 0, 10
